-- ============================================================================
-- B5 FOLLOW-ON W3 (Suite Full precision): heattransfer capstone brief.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 2 and
-- the section 1 Suite rows, decision D3 (owner approved D1 to D7 as
-- recommended, 2026-09-21). The Suite app the capstone is read in gains a
-- "Full precision" switch, off by default, that prints the graded quantities
-- at the precision they are graded to. The brief now says to switch it on.
--
-- INTERMEDIATE
--   Fields read with the switch on: ubit_f_correction, ubit_p1_two_shells.
--   The Sizer rounds F to 3 decimals and never showed the equivalent
--   single-shell P; the prompt asks 6.
--   APPENDED: Read the figures in the Heat Exchanger Sizer with its Full
--   precision switch on (at the top of the page): it prints them to the
--   precision this capstone grades, with no digit grouping.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance, and their order), title, dataset, status and the row. The guard
-- requires `fields` to equal its post-W1 value exactly, before and after, so
-- no answer grades differently and no attempts guard is needed.
--
-- ORDER. Apply only once the Suite build carrying the W3 switch is live (the
-- brief names it). Runs after W1 (20261024*): refuses without it.
--
-- GUARDS. Each prompt must hold its post-W1 text (md5, rewritten) or its W3
-- text (left alone), with the exact fields. Anything else raises and the file
-- rolls back. Generated by docs/graded-field-audit/w3_capstones.py from
-- w3/heattransfer.json. SAFE TO RE-RUN: a second run writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_s0       text;
begin
  -- heattransfer / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'heattransfer' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w3 heattransfer refused: heattransfer/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '3446e2133c845a60e6fb3c712ad7b6f4' and fields = '[{"key": "ubit_f_correction", "tol": 5E-7, "unit": "fraction", "label": "The correction factor at one shell pass", "expected": 0.8879617104201317}, {"key": "ubit_p1_two_shells", "tol": 5E-7, "unit": "fraction", "label": "The equivalent single-shell P at two shells in series", "expected": 0.23359328643184238}, {"key": "ubit_u_clean", "tol": 0.000001, "unit": "Btu/hr.ft2.F", "label": "The clean overall coefficient, referred to the outside tube surface", "expected": 197.05374899995743}, {"key": "ubit_u_dirty", "tol": 0.000001, "unit": "Btu/hr.ft2.F", "label": "The dirty overall coefficient, referred to the same outside surface", "expected": 104.43380596479474}, {"key": "ubit_fouling_penalty_pct", "tol": 0.000001, "unit": "percent", "label": "What the two fouling allowances cost that coefficient", "expected": 47.002375496638074}, {"key": "ubit_controlling_margin_pct", "tol": 0.000001, "unit": "percent", "label": "How far the controlling resistance leads the next one", "expected": 20.48182441700959}]'::jsonb then 'old'
              when md5(prompt) = '3084af74ff905da810f124720730aec0' and fields = '[{"key": "ubit_f_correction", "tol": 5E-7, "unit": "fraction", "label": "The correction factor at one shell pass", "expected": 0.8879617104201317}, {"key": "ubit_p1_two_shells", "tol": 5E-7, "unit": "fraction", "label": "The equivalent single-shell P at two shells in series", "expected": 0.23359328643184238}, {"key": "ubit_u_clean", "tol": 0.000001, "unit": "Btu/hr.ft2.F", "label": "The clean overall coefficient, referred to the outside tube surface", "expected": 197.05374899995743}, {"key": "ubit_u_dirty", "tol": 0.000001, "unit": "Btu/hr.ft2.F", "label": "The dirty overall coefficient, referred to the same outside surface", "expected": 104.43380596479474}, {"key": "ubit_fouling_penalty_pct", "tol": 0.000001, "unit": "percent", "label": "What the two fouling allowances cost that coefficient", "expected": 47.002375496638074}, {"key": "ubit_controlling_margin_pct", "tol": 0.000001, "unit": "percent", "label": "How far the controlling resistance leads the next one", "expected": 20.48182441700959}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'heattransfer' and tier = 'intermediate' and active;
  if v_s0 = 'other' then
    raise exception 'w3 heattransfer refused: heattransfer/intermediate matches neither its post-W1 form (prompt md5 3446e2133c845a60e6fb3c712ad7b6f4) nor its W3 form (prompt md5 3084af74ff905da810f124720730aec0), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W3 form
  if v_s0 = 'new' then
    raise notice 'w3 heattransfer: 0 of 1 row(s) written, all already applied';
    return;
  end if;

  -- W1 (20261024*) must be applied first: its rows are this file's base
  if not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'seismolord' and c.tier = 'intermediate' and c.active and f->>'key' = 'corr_zero_lag')
     or not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'mbal' and c.tier = 'beginner' and c.active and f->>'key' = 'eo_last_rb_stb')
     or not exists (select 1 from public.academy_capstones
                  where app_slug = 'basin' and tier = 'beginner' and active and prompt like 'Open book%') then
    raise exception 'w3 heattransfer refused: W1 (20261024*) is not applied on this database; apply it first (/root/w1-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'UBIT, the shell-and-tube train. The four terminals are a hot stream entering at 405 degF and leaving at 265 degF against a cold stream entering at 135 degF and leaving at 233 degF. Read the correction factor first at ONE shell pass, then take the same duty into TWO shells in series. The coefficient is assembled from five named resistances on a tube of 0.875 inch outside diameter and 0.729 inch inside diameter. Both film coefficients are STATED as conditions of this study, 265 Btu per hr ft2 degF outside and 1120 inside, and so is the wall conductivity of 29 Btu per hr ft degF, so nothing here is looked up. The fouling allowances are 0.0015 hr ft2 degF per Btu outside and 0.0025 inside. Report six values: the correction factor at one shell pass, the equivalent single-shell P at two shells in series, the clean overall coefficient, the dirty one, what the two fouling allowances cost as a percentage of the clean coefficient, and how far the controlling resistance leads the runner up as a percentage of itself. Correction factors and equivalent P as a fraction, coefficients in Btu per hr ft2 degF and both percentages in percent, all to six decimals. Read the figures in the Heat Exchanger Sizer with its Full precision switch on (at the top of the page): it prints them to the precision this capstone grades, with no digit grouping.'
     where app_slug = 'heattransfer' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w3 heattransfer refused: heattransfer/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '3084af74ff905da810f124720730aec0' and fields = '[{"key": "ubit_f_correction", "tol": 5E-7, "unit": "fraction", "label": "The correction factor at one shell pass", "expected": 0.8879617104201317}, {"key": "ubit_p1_two_shells", "tol": 5E-7, "unit": "fraction", "label": "The equivalent single-shell P at two shells in series", "expected": 0.23359328643184238}, {"key": "ubit_u_clean", "tol": 0.000001, "unit": "Btu/hr.ft2.F", "label": "The clean overall coefficient, referred to the outside tube surface", "expected": 197.05374899995743}, {"key": "ubit_u_dirty", "tol": 0.000001, "unit": "Btu/hr.ft2.F", "label": "The dirty overall coefficient, referred to the same outside surface", "expected": 104.43380596479474}, {"key": "ubit_fouling_penalty_pct", "tol": 0.000001, "unit": "percent", "label": "What the two fouling allowances cost that coefficient", "expected": 47.002375496638074}, {"key": "ubit_controlling_margin_pct", "tol": 0.000001, "unit": "percent", "label": "How far the controlling resistance leads the next one", "expected": 20.48182441700959}]'::jsonb) from public.academy_capstones where app_slug = 'heattransfer' and tier = 'intermediate' and active) is not true then
    raise exception 'w3 heattransfer refused: heattransfer/intermediate does not read back as its W3 form';
  end if;

  raise notice 'w3 heattransfer: % of 1 row(s) written, % already applied', v_written, 1 - v_written;
end $$;
